public sealed record CreateRecipeRequest(string TenantKey, string ProductSku, int Version, string ProcessStep, string OutputUom, decimal TargetYieldPercent, IReadOnlyList<RecipeComponentRequest>? Components = null, bool Active = true);
public sealed record RecipeComponentRequest(string IngredientSku, decimal Quantity, string Uom);
public sealed record RecipeDto(Guid Id, string TenantKey, string ProductSku, int Version, string ProcessStep, string OutputUom, decimal TargetYieldPercent, bool Active, IReadOnlyList<RecipeComponentDto> Components, DateTimeOffset CreatedAt);
public sealed record RecipeComponentDto(string IngredientSku, decimal Quantity, string Uom);
public sealed record CreateMachineRequest(string TenantKey, string Code, string Name, string Status = "Available", DateTimeOffset? LastMaintenanceAt = null, DateTimeOffset? NextMaintenanceAt = null, bool Active = true);
