public sealed record CreateProductionOrderRequest(string OrderNumber, string ProductSku, Guid RecipeId, decimal TargetQuantity, string OutputUom);
public sealed record ProductionOrderDto(Guid Id, string TenantKey, string OrderNumber, string ProductSku, Guid RecipeId, int RecipeVersion, decimal TargetQuantity, string OutputUom, string Status, DateTimeOffset CreatedAt, DateTimeOffset? ReleasedAt);
public sealed record CreateProductionBatchRequest(Guid ProductionOrderId, string BatchNumber, decimal? PlannedQuantity = null, Guid? MachineId = null);
public sealed record ProductionBatchDto(Guid Id, string TenantKey, Guid ProductionOrderId, string BatchNumber, string Status, decimal PlannedQuantity, decimal ActualOutputQuantity, Guid? MachineId, DateTimeOffset CreatedAt, DateTimeOffset? StartedAt, DateTimeOffset? CompletedAt, IReadOnlyList<OperationExecutionDto> Operations);
